import type {
	HTMLWordCloudElement,
	WordRemoveOptions,
} from "./word-cloud-element"

/**
 * Plain serializable data that describes a word. Used as input for
 * {@link HTMLWordCloudElement.add}.
 */
export interface WordData {
	/** The displayed word content. */
	word: string
	/** Horizontal center position in pixels. */
	x: number
	/** Vertical center position in pixels. */
	y: number
	/** Rotation in radians. Defaults to `0`. */
	angle?: number
	/** Checked state. Defaults to `false`. */
	checked?: boolean
}

interface WordHandleConfig {
	getX: () => number
	getY: () => number
	getWord: () => string
	setWord: (word: string) => void
	getAngle: () => number
	getChecked: () => boolean
	setChecked: (checked: boolean) => void
	remove: (options?: WordRemoveOptions) => void
}

/**
 * A live handle to a word managed by {@link HTMLWordCloudElement}.
 *
 * All property reads reflect the current physics position and DOM state —
 * there is no stale snapshot. Obtain instances via
 * {@link HTMLWordCloudElement.add} or {@link HTMLWordCloudElement.getWords}.
 */
export class WordHandle implements Readonly<WordData> {
	#config: WordHandleConfig

	/** @internal */
	constructor(data: WordHandleConfig) {
		this.#config = data
	}

	/** The displayed text of this word. */
	get word(): string {
		return this.#config.getWord()
	}

	/**
	 * Programmatically updates the displayed text of this word.
	 *
	 * @param value The new text to display.
	 */
	set word(value: string) {
		this.#config.setWord(value)
	}

	/** Current horizontal center position in pixels. */
	get x(): number {
		return this.#config.getX()
	}

	/** Current vertical center position in pixels. */
	get y(): number {
		return this.#config.getY()
	}

	/** Current rotation of the physics body in radians. */
	get angle(): number {
		return this.#config.getAngle()
	}

	/** Whether this word is currently marked as checked. */
	get checked(): boolean {
		return this.#config.getChecked()
	}

	/**
	 * Programmatically sets the checked state of this word.
	 * Triggers a `word-check` event on the parent cloud element if the
	 * value actually changes.
	 *
	 * @param value The new checked state.
	 */
	set checked(value: boolean) {
		this.#config.setChecked(value)
	}

	/**
	 * Removes this word from the cloud.
	 * Dispatches a `word-delete` event from the parent cloud element.
	 *
	 * @param options (optional) Additional options for the removal operation.
	 * Supported options:
	 * - `exitAnimation`: exit animation to run when the word is removed.
	 * Supported values are `"fade"`, and `"none"`. Defaults to `"fade"`.
	 */
	remove(options?: WordRemoveOptions): void {
		this.#config.remove(options)
	}
}
